    :param float|int seconds:
    :return str: 'h:m:s"
    """
def sec2time(seconds: Any) -> object {
    (m, s) = divmod(seconds, 60);
    (h, m) = divmod(m, 60);
    return ("%d:%02d:%02d" % (h, m, s));
}

